import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Suspense } from "react";
import { BadgeCheck, RotateCcw, ShieldCheck, Sparkles, Truck } from "lucide-react";
import { getNewArrivals, getProductBySlug, getProductReviews, getRelatedProducts } from "@/lib/catalog";
import { getCurrentUser } from "@/lib/auth";
import { formatINR } from "@/lib/money";
import { EMI_MIN_AMOUNT, SITE } from "@/lib/site";
import { formatDate } from "@/lib/utils";
import { ProductGallery } from "@/components/store/ProductGallery";
import { BuyBox } from "@/components/store/BuyBox";
import { EmiPlans } from "@/components/store/EmiPlans";
import { AffordabilityWidget } from "@/components/store/AffordabilityWidget";
import { Price } from "@/components/store/Price";
import { Stars } from "@/components/store/Stars";
import { ProductRail } from "@/components/store/ProductCard";
import { ReviewForm } from "@/components/store/ReviewForm";
import { ViewTracker } from "@/components/store/ViewTracker";
import { RecentlyViewed, RecordView } from "@/components/store/RecentlyViewed";
import { Reveal } from "@/components/store/Reveal";

export async function generateStaticParams() {
  const products = await getNewArrivals(50);
  return products.map((p) => ({ slug: p.slug }));
}

export async function generateMetadata({ params }: PageProps<"/product/[slug]">): Promise<Metadata> {
  const p = await getProductBySlug((await params).slug);
  if (!p) return { title: "Product not found" };
  return {
    title: p.name,
    description: p.shortDescription ?? undefined,
    openGraph: { title: p.name, description: p.shortDescription ?? undefined, images: p.images.slice(0, 1).map((i) => i.url) },
  };
}

type Spec = { label: string; value: string };

async function Reviews({ productId, ratingAvg, ratingCount }: { productId: string; ratingAvg: number; ratingCount: number }) {
  const { reviews, distribution } = await getProductReviews(productId);
  return (
    <section id="reviews" className="grid gap-8 border-t border-line py-8 md:grid-cols-[280px_1fr]">
      <div>
        <h2 className="font-display text-2xl font-semibold">Customer reviews</h2>
        <div className="mt-2 flex items-center gap-2"><Stars value={ratingAvg} size={18} /><span className="font-semibold">{ratingAvg.toFixed(1)} out of 5</span></div>
        <p className="text-sm text-muted">{ratingCount} global ratings</p>
        <div className="mt-4 space-y-1.5">
          {distribution.map((d) => (
            <div key={d.rating} className="flex items-center gap-2 text-sm">
              <span className="w-12">{d.rating} star</span>
              <div className="h-4 flex-1 overflow-hidden rounded bg-line/60"><div className="h-full origin-left animate-[grow-x_900ms_var(--ease-out)_both] bg-brass" style={{ width: `${ratingCount ? (d.count / ratingCount) * 100 : 0}%` }} /></div>
              <span className="w-8 text-right text-muted">{ratingCount ? Math.round((d.count / ratingCount) * 100) : 0}%</span>
            </div>
          ))}
        </div>
        <div className="mt-6">
          <p className="font-semibold">Review this product</p>
          <Suspense fallback={null}>
            <ReviewGate productId={productId} />
          </Suspense>
        </div>
      </div>
      <div className="space-y-6">
        {reviews.length === 0 && <p className="text-sm text-muted">No reviews yet. Be the first to share your experience.</p>}
        {reviews.map((r) => (
          <article key={r.id}>
            <p className="text-sm font-medium">{r.user.name}</p>
            <div className="flex items-center gap-2"><Stars value={r.rating} />{r.title && <span className="text-sm font-semibold">{r.title}</span>}</div>
            <p className="text-xs text-muted">Reviewed on {formatDate(r.createdAt)}{r.verifiedPurchase && <span className="ml-2 font-semibold text-brass">Verified Purchase</span>}</p>
            {r.body && <p className="mt-1 text-sm">{r.body}</p>}
          </article>
        ))}
      </div>
    </section>
  );
}

async function ReviewGate({ productId }: { productId: string }) {
  const user = await getCurrentUser();
  if (!user) return <p className="mt-1 text-sm"><Link href="/login" className="font-semibold text-maroon hover:underline">Sign in</Link> to write a review.</p>;
  return <div className="mt-2"><ReviewForm productId={productId} /></div>;
}

async function Related({ categoryId, id }: { categoryId: string; id: string }) {
  const related = await getRelatedProducts(categoryId, id);
  return <ProductRail title="Customers also viewed" products={related} />;
}

async function ProductContent({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const p = await getProductBySlug(slug);
  if (!p) notFound();
  const specs = (Array.isArray(p.specs) ? p.specs : []) as Spec[];
  const emi = p.emiEligible && p.price >= EMI_MIN_AMOUNT;

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "Product",
    name: p.name,
    sku: p.sku,
    image: p.images.map((i) => `${SITE.url}${i.url}`),
    description: p.shortDescription,
    brand: { "@type": "Brand", name: p.brand ?? SITE.name },
    ...(p.ratingCount ? { aggregateRating: { "@type": "AggregateRating", ratingValue: p.ratingAvg.toFixed(1), reviewCount: p.ratingCount } } : {}),
    offers: {
      "@type": "Offer",
      priceCurrency: "INR",
      price: (p.price / 100).toFixed(2),
      availability: p.stock > 0 ? "https://schema.org/InStock" : "https://schema.org/OutOfStock",
      seller: { "@type": "Organization", name: SITE.name },
      url: `${SITE.url}/product/${p.slug}`,
    },
  };

  return (
    <>
      <Suspense fallback={null}>
        <ViewTracker productId={p.id} />
      </Suspense>
      <RecordView item={{ id: p.id, slug: p.slug, name: p.name, price: p.price, image: p.images[0]?.url ?? null }} />
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd).replace(/</g, "\\u003c") }} />
      <nav className="mb-4 text-xs text-muted" aria-label="Breadcrumb">
        <Link href="/" className="hover:underline">Home</Link> ›{" "}
        {p.category.parent && <><Link href={`/category/${p.category.parent.slug}`} className="hover:underline">{p.category.parent.name}</Link> › </>}
        <Link href={`/category/${p.category.slug}`} className="hover:underline">{p.category.name}</Link>
      </nav>

      <div className="grid gap-8 lg:grid-cols-[1.1fr_1fr_300px]">
        <ProductGallery images={p.images} name={p.name} productId={p.id} />

        <div className="animate-fade-up space-y-4">
          {p.brand && <p className="text-sm font-semibold text-brass">Brand: {p.brand}</p>}
          <h1 className="font-display text-2xl font-semibold leading-tight sm:text-3xl">{p.name}</h1>
          {p.ratingCount > 0 && (
            <a href="#reviews" className="flex items-center gap-2 text-sm"><span>{p.ratingAvg.toFixed(1)}</span><Stars value={p.ratingAvg} /><span className="text-maroon hover:underline">{p.ratingCount} ratings</span></a>
          )}
          <hr className="border-line" />
          <Price price={p.price} mrp={p.mrp} size="lg" />
          <p className="text-xs text-muted">Inclusive of all taxes ({p.gstRate}% GST){p.hsnCode && ` · HSN ${p.hsnCode}`}</p>
          {emi && <EmiPlans price={p.price} />}
          {emi && <AffordabilityWidget keyId={process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID || undefined} amount={p.price} />}

          <div className="grid grid-cols-4 gap-2 border-y border-line py-4 text-center text-[11px] text-ink-soft">
            <div><Truck className="mx-auto mb-1 h-6 w-6 text-brass" aria-hidden />Free delivery above ₹999</div>
            <div><RotateCcw className="mx-auto mb-1 h-6 w-6 text-brass" aria-hidden />7-day replacement</div>
            <div><ShieldCheck className="mx-auto mb-1 h-6 w-6 text-brass" aria-hidden />{p.warranty ? "Warranty" : "Genuine product"}</div>
            <div><BadgeCheck className="mx-auto mb-1 h-6 w-6 text-brass" aria-hidden />GST invoice</div>
          </div>

          {p.engravingAvailable && (
            <p className="flex gap-2 rounded-md bg-brass-light/60 p-3 text-sm"><Sparkles className="h-5 w-5 shrink-0 text-brass" aria-hidden />Personalise with free fiber laser engraving — add a name or message before adding to cart.</p>
          )}

          {specs.length > 0 && (
            <table className="w-full text-sm">
              <tbody>
                {p.material && <tr><th className="w-40 py-1 pr-4 text-left font-semibold">Material</th><td>{p.material}</td></tr>}
                {specs.map((s) => <tr key={s.label}><th className="py-1 pr-4 text-left font-semibold">{s.label}</th><td>{s.value}</td></tr>)}
                {p.warranty && <tr><th className="py-1 pr-4 text-left font-semibold">Warranty</th><td>{p.warranty}</td></tr>}
              </tbody>
            </table>
          )}

          {p.shortDescription && (
            <div>
              <h2 className="mb-1 font-semibold">About this item</h2>
              <p className="text-sm text-ink-soft">{p.shortDescription}</p>
            </div>
          )}
        </div>

        <div className="lg:sticky lg:top-36 lg:self-start">
          <BuyBox productId={p.id} name={p.name} price={p.price} mrp={p.mrp} stock={p.stock} engravingAvailable={p.engravingAvailable} />
          <p className="mt-3 text-xs text-muted">Sold by <span className="font-semibold text-ink">{SITE.name}</span>, Cheyyur. SKU {p.sku}.{p.price >= EMI_MIN_AMOUNT && !p.emiEligible && " EMI not available on this item."}</p>
        </div>
      </div>

      <Reveal as="section" className="prose-store mt-10 max-w-4xl border-t border-line pt-8">
        <h2 className="mb-3 font-display text-2xl font-semibold">Product description</h2>
        {p.description.split(/\n{2,}/).map((para, i) => <p key={i} className="whitespace-pre-line text-sm text-ink-soft">{para}</p>)}
        {p.weightGrams ? <p className="text-sm text-muted">Shipping weight: {(p.weightGrams / 1000).toFixed(2)} kg · Price {formatINR(p.price)}</p> : null}
      </Reveal>

      <Suspense fallback={<div className="h-64" />}>
        <Related categoryId={p.categoryId} id={p.id} />
      </Suspense>
      <Suspense fallback={<div className="h-64" />}>
        <Reviews productId={p.id} ratingAvg={p.ratingAvg} ratingCount={p.ratingCount} />
      </Suspense>
      <RecentlyViewed excludeId={p.id} />
    </>
  );
}

export default function ProductPage({ params }: PageProps<"/product/[slug]">) {
  return (
    <div className="container-x py-6">
      <Suspense
        fallback={
          <div className="grid gap-8 lg:grid-cols-[1.1fr_1fr_300px]"><div className="skeleton aspect-square rounded-xl" /><div className="skeleton h-96 rounded-xl" /><div className="skeleton h-80 rounded-xl" /></div>
        }
      >
        <ProductContent params={params} />
      </Suspense>
    </div>
  );
}
